// real, src/manager.ts::requireSession (trimmed)
private requireSession(sessionId: string): Session {
  const session = this.sessions.get(sessionId);
  if (!session) throw new PasswordManagerError("UNKNOWN_SESSION", ...);
  ...
  if (this.clock.now() - session.lastActivityAt > this.sessionIdleTimeoutMs) {
    this.sessions.delete(sessionId); // lazy cleanup, no background sweep
    throw new PasswordManagerError("SESSION_IDLE_TIMEOUT", ...);
  }
  session.lastActivityAt = this.clock.now(); // using the session is what keeps it alive
  return session;
}

// real, src/circuit-breaker.ts::run (trimmed)
async run<T>(fn: () => Promise<T>): Promise<T> {
  if (this.state === "open") {
    if (this.openedAt !== null && this.clock.now() - this.openedAt >= this.cooldownMs) {
      this.state = "half-open";
    } else {
      throw new Error("CIRCUIT_OPEN"); // fn() is never even called
    }
  }
  try {
    const result = await fn();
    this.consecutiveFailures = 0;
    this.state = "closed";
    return result;
  } catch (err) {
    this.consecutiveFailures++;
    if (this.state === "half-open" || this.consecutiveFailures >= this.failureThreshold) {
      this.state = "open";
      this.openedAt = this.clock.now();
    }
    throw err;
  }
}

